const request = require('request');
const db = require('./db');

function fetchPage(page, cb) {
  request.get(`https://api.example.com/items?page=${page}`, (err, res, body) => {
    if (err) return cb(err);
    if (res.statusCode !== 200) return cb(new Error(`HTTP ${res.statusCode}`));
