function run(startPage, cb) {
  let page = startPage;
  let total = 0;
  (function loop() {
    if (!page) return cb(null, total);
    processPage(page, (err, result) => {
      if (err) return cb(err);
      total += result.count;
      page = result.nextPage;
      loop();
