{"path": "ring.c", "content": "#include "ring.h"

void ring_init(ring_t *r) {
    r->head = 0;
    r->tail = 0;
    r->count = 0;
}

int ring_push(ring_t *r, uint8_t value) {
    if (r->count == 16) return -1;
    r->data[r->head] = value;
    r->head = (r->head + 1) & 15; // mask for power of two
    r->count++;
    return 0;
}

int ring_pop(ring_t *r, uint8_t *out) {
    if (r->count == 0) return -1;
    *out = r->data[r->tail];
    r->tail = (r->tail + 1) & 15;
    r->count--;
    return 0;
}

size_t ring_size(const ring_t *r) { return r->count; }

int ring_full(const ring_t *r) { return r->count == 16; }

int ring_empty(const ring_t *r) { return r->count == 0; }
"}

