# game_logic.py
class Rect:
    def __init__(self, x, y, w, h):
        self.x = x
        self.y = y
        self.w = w
        self.h = h

def check_collision(rect1, rect2):
    # Check for overlap (axis-aligned bounding boxes)
    if (rect1.x < rect2.x + rect2.w and
        rect1.x + rect1.w > rect2.x and
        rect1.y < rect2.y + rect2.h and
        rect1.y + rect1.h > rect2.y):
        return True
    else:
        return False

def update_score(current_score, hit):
    # hit is a boolean indicating whether a target was hit
    if hit:
        return current_score + 100
    else:
        return max(0, current_score - 50)
