const { Pool } = require('pg');
const pool = new Pool({ connectionString: 'postgres://user:pass@localhost:5432/churn_db' });

const reasons = ['Pricing', 'Feature Gap', 'Poor Support', 'Other'];

async function seed() {
  await pool.query('TRUNCATE churn_events');
  const inserts = [];
  for (let m = 0; m < 12; m++) {
    const date = new Date(2023, 5 + m, 1); // start June 2023
    const numEvents = Math.floor(Math.random() * 31) + 20; // 20-50
    for (let i = 0; i < numEvents; i++) {
      const day = Math.floor(Math.random() * 28) + 1;
      const eventDate = new Date(date.getFullYear(), date.getMonth(), day);
      const reason = reasons[Math.floor(Math.random() * reasons.length)];
      inserts.push(pool.query(
        'INSERT INTO churn_events (event_date, reason) VALUES ($1, $2)',
        [eventDate.toISOString().slice(0,10), reason]
      ));
    }
  }
  await Promise.all(inserts);
  console.log('Seeded churn events');
  process.exit();
}

seed().catch(err => { console.error(err); process.exit(1); });
