```javascript
// core.js
class PRNG {
  constructor(seed) {
    this.seed = seed >>> 0;
  }
  next() {
    this.seed = (this.seed * 1103515245 + 12345) % 2147483648;
    return this.seed / 2147483648;
  }
}

class GameState {
  constructor(seed) {
    this.seed = seed;
    this.rng = new PRNG(seed);
    this.player = new Player();
    this.monsters = [];
    this.rooms = [];
    // generate 4x4 grid, rooms with 30% monster chance, (3,3) treasure
    for (let y=0; y<4; y++) {
      this.rooms[y] = [];
      for (let x=0; x<4; x++) {
        if (x===3 && y===3) this.rooms[y][x] = new Room('treasure');
        else if (this.rng.next() < 0.3) this.rooms[y][x] = new Room('monster');
        else this.rooms[y][x] = new Room('empty');
      }
    }
    this.player.pos = {x:0, y:0};
  }
}
// ... Player, Monster, Room, move_player, fight_monster, check_win ...
module.exports = { GameState, PRNG, Player, Monster, Room, move_player, fight_monster, check_win };
